export interface FactoryRunUsage {
  factoryRunUsageId: number;
  factoryRunRef: string;
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
  costUSD: number;
  modelName: string;
  timestamp: string;
  created_At: string;
  updated_at?: string;
}

export interface FactoryRunUsageListResponse {
  factoryRunUsages: FactoryRunUsage[];
}

// GET ALL — POST /all_factoryRunUsages
export async function getAllFactoryRunUsages(): Promise<FactoryRunUsage[]> {
  // Module is TENANT_INDEPENDENT, so companyId is not sent.
  const res = await fetch(BASE_URL + "/all_factoryRunUsages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRunUsages": [{}] }), // Backend expects plural key with empty object for all
  });
  if (!res.ok) throw new Error(await res.text());
  const data: FactoryRunUsageListResponse = await res.json();
  return data.factoryRunUsages ?? [];
}

// CREATE — action: 1
export async function createFactoryRunUsage(payload: Omit<FactoryRunUsage, "factoryRunUsageId" | "totalTokens" | "created_At" | "updated_at">): Promise<FactoryRunUsage> {
  const res = await fetch(BASE_URL + "/factoryRunUsages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRunUsages": [{ "action": 1, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// UPDATE — action: 2
export async function updateFactoryRunUsage(id: number, payload: Partial<Omit<FactoryRunUsage, "created_At" | "updated_at" | "totalTokens" | "factoryRunUsageId">>): Promise<FactoryRunUsage> {
  const res = await fetch(BASE_URL + "/factoryRunUsages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRunUsages": [{ "action": 2, "factoryRunUsageId": id, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// DELETE — action: 3
export async function deleteFactoryRunUsage(id: number): Promise<void> {
  // Module is TENANT_INDEPENDENT, so companyId is not sent.
  const res = await fetch(BASE_URL + "/factoryRunUsages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRunUsages": [{ "action": 3, "factoryRunUsageId": id }] }),
  });
  if (!res.ok) throw new Error(await res.text());
}
